// Parcourir le tableau
foreach ($info as $index => $row) {
    try {
        // Extraire les données
        $code            = trim($row[0]);
        $nom             = trim($row[1]);
        $prenom          = trim($row[2]);
        $sexeCode        = trim($row[3]);
        $dateNaissance   = $row[4];
        $anneeAcademique = trim($row[7]); // Ex: 2018/2019
