        // 1. Vérifier/Créer l'étudiant;
        $etudiant = Etudiant::where('code', $code)->first();

        $anneeAcademiqueModel = AnneeAcademique::where('annee_academique', $anneeAcademique)->first();
        $inscriptionDate      = getInscriptionDate($anneeAcademique);

        if (! $etudiant) {
            // Créer l'étudiant
            $identifiant = generateUniqueIdentifiant();

            echo "  👤 Création étudiant avec identifiant: $identifiant\n";

            $etudiant = Etudiant::create([
                'id'                => (string) Str::uuid(),
                'identifiant'       => $identifiant,
                'code'              => $code,
                'nom'               => $nom,
                'prenom'            => $prenom,
                'sexe'              => $sexe,
                'date_de_naissance' => $dateNaissance,
                'adresse'           => 'Leogane',
                'aide_financiere'   => 'Aucune',
                'created_at'        => $inscriptionDate,
                'updated_at'        => $inscriptionDate,

            ]);

            echo "  ✅ Nouvel étudiant créé (ID: {$etudiant->id})\n";
        } else {
            echo "  👤 Étudiant existant (ID: {$etudiant->id})\n";
        }

        // 2. Récupérer l'année académique
        //    $anneeAcademiqueModel = AnneeAcademique::where('annee_academique', $anneeAcademique)->first();

        if (! $anneeAcademiqueModel) {
            $errors[] = "Année académique '$anneeAcademique' introuvable ligne " . ($index + 1);
            echo "  ❌ Année académique '$anneeAcademique' introuvable\n\n";
            continue;
        }

        echo "  📅 Année académique trouvée (ID: {$anneeAcademiqueModel->id})\n";

        // 3. Récupérer la classe
        $classe = Classes::where('nom_classe', $nomClasse)->first();

        if (! $classe) {
            $errors[] = "Classe '$nomClasse' introuvable ligne " . ($index + 1);
            echo "  ❌ Classe '$nomClasse' introuvable\n\n";
            continue;
        }

        echo "  🏫 Classe trouvée (ID: {$classe->id}, Niveau ID: {$classe->niveau_id})\n";

        $cours_etudiant = CoursEtudiant::where('etudiant_id', $etudiant->id)
        //   ->where('classe', $classe->id)
            ->where('annee_academique', $anneeAcademiqueModel->annee_academique)
            ->first();

        if (! $cours_etudiant) {
            CoursEtudiant::updateOrCreate(
                [
                    'etudiant_id'      => $etudiant->id, // ID de l'étudiant
                    'annee_academique' => $anneeAcademiqueModel->annee_academique,
                ],
                [
                    'niveau'        => $classe->niveau_id,
                    'code'          => $code,
                    'faculte'       => null,
                    'identifiant'   => $etudiant->identifiant,
                    'classe'        => $classe->id,
                    'data_etudiant' => json_encode([]),
                    'created_at'    => $inscriptionDate,
                    'updated_at'    => $inscriptionDate,
                ]
            );

        }

        // Before your existing check, add this debugging
        echo "Checking etudiant_id: {$etudiant->id}, classes_id: {$classe->id}, annee_academique_id: {$anneeAcademiqueModel->id}\n";

        $exists = ClassesEtudiant::where('etudiant_id', $etudiant->id)
            ->where('niveau_id', $classe->niveau_id)
            ->where('annee_academique_id', $anneeAcademiqueModel->id)
            ->first();

        //    if ($exists) {
        //        echo "  ⏭️  Déjà existant\n\n";
        //        $totalSkipped++;

        //        // ADD THIS: Find and display when this record was created
        //        $existingRecord = ClassesEtudiant::where('etudiant_id', $etudiant->id)
        //            ->where('classes_id', $classe->id)
        //            ->where('annee_academique_id', $anneeAcademiqueModel->id)
        //            ->first();

        //        echo "  Existing record created at: " . $existingRecord->created_at . "\n";
        //        echo "  Existing record ID: " . $existingRecord->id . "\n\n";

        //        continue;
        //    }

        // 5. Calculer les dates created_at et updated_at basées sur l'année académique
        //    $inscriptionDate = getInscriptionDate($anneeAcademique);
        if (! $exists) {
            echo "  📆 Date d'inscription: {$inscriptionDate}\n";

            // 6. Insérer dans classes_etudiants
            $classeEtudiant = new ClassesEtudiant([
                'id'                  => (string) Str::uuid(),
                'etudiant_id'         => $etudiant->id,
                'classes_id'          => $classe->id,
                'annee_academique_id' => $anneeAcademiqueModel->id,
                'niveau_id'           => $classe->niveau_id,
                'user_id'             => null,
                'status'              => 1,
            ]);

            // Définir manuellement les timestamps
            $classeEtudiant->created_at = $inscriptionDate;
            $classeEtudiant->updated_at = $inscriptionDate;

            $classeEtudiant->save();
        }

        echo "  ✅ Inséré avec succès\n\n";
        $totalInserted++;

    } catch (\Throwable $e) {
        $errors[] = "Ligne " . ($index + 1) . ": " . $e->getMessage();
        echo "  ❌ Erreur: " . $e->getMessage() . "\n\n";
    }
}

// Résumé
echo "\n=================================\n";
echo "📊 RÉSUMÉ DE L'IMPORT\n";
echo "=================================\n";
echo "✅ Insérés: $totalInserted\n";
echo "⏭️  Ignorés: $totalSkipped\n";
echo "❌ Erreurs: " . count($errors) . "\n";

if (count($errors) > 0) {
    echo "\n❌ LISTE DES ERREURS:\n";
    foreach ($errors as $error) {
        echo " -$error\n";
    }
}

// ==================== FONCTIONS ====================

/**
 * Générer un identifiant unique au format 1-XXXXX
 */
function generateUniqueIdentifiant()
{
    do {
        $randomPart  = str_pad(rand(0, 99999), 5, '0', STR_PAD_LEFT);
        $identifiant = '1-' . $randomPart;
    } while (Etudiant::where('identifiant', $identifiant)->exists());

    return $identifiant;
}

/**
 * Calculer la date d'inscription basée sur l'année académique
 * Format: 2018/2019 → Septembre 2018
 *
 * @param string $anneeAcademique Format: "2018/2019"
 * @return Carbon
 */
function getInscriptionDate($anneeAcademique)
{
    // Extraire la première année
    $years     = explode('/', $anneeAcademique);
    $firstYear = $years[0];

    // Créer une date en septembre de la première année
    // Jour aléatoire entre 1 et 30 septembre pour varier un peu
    $day = rand(1, 30);

    return Carbon::create($firstYear, 9, $day, rand(8, 17), rand(0, 59), rand(0, 59));
}
